window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-4050d20ac47aa707"]={"versions": [{"id": "FIG-4050d20ac47aa707", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des ECU-Konfigurationsparametersatzes (ECUC) für das AUTOSAR-BswM-/EcuM-Modul <code>EcuMFixed</code> (ECU State Manager Fixed). Dargestellt ist die Metamodell-Struktur des Konfigurationscontainers <code>EcuMFixedGeneral</code> mit seinen enthaltenen Parametern und Referenzen sowie die Beziehung zum allgemeinen EcuM-Container <code>EcuMWakeupSource</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li>Container <code>EcuMFixedGeneral: EcucParamConfContainerDef</code> mit Multiplizität <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>.</li>\n<li>Aggregierte Konfigurationsparameter (<code>+parameter</code> via Komposition):</li>\n<li><code>EcuMTTIIEnabled: EcucBooleanParamDef</code> (Aktivierung von Time-Triggered Interfaces).</li>\n<li><code>EcuMIncludeNvramMgr: EcucBooleanParamDef</code> (Einbindung des NVRAM-Managers).</li>\n<li><code>EcuMIncludeNvM: EcucBooleanParamDef</code> (Einbindung des NVM-Treibers/Moduls).</li>\n<li><code>EcuMIncludeComM: EcucBooleanParamDef</code> (Einbindung des Communication Managers).</li>\n<li>Aggregierte Referenz (<code>+reference</code> via Komposition):</li>\n<li><code>EcuMTTIIWakeupSourceRef: EcucSymbolicNameReferenceDef</code> verweist mit <code>+destination</code> auf den externen Container <code>EcuMWakeupSource: EcucParamConfContainerDef</code> (from <code>EcuM</code>) mit Multiplizität <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = *</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne Ausführungssemantik oder Laufzeitsequenzen. Die Parameter steuern die Codegenerierung bzw. Vorkompilierungsvarianten (z. B. Einbindung von NvM, NvramMgr, ComM und TTII-Unterstützung). Die symbolische Referenz <code>EcuMTTIIWakeupSourceRef</code> verknüpft die Time-Triggered-Interface-Funktionalität mit einer oder mehreren im System definierten Weckquellen (<code>EcuMWakeupSource</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Konfigurationsspezifikation für AUTOSAR Classic BSW-Generatoren. Implementierer und Konfiguratoren müssen beachten:</p>\n<ul class=\"fig-list\">\n<li>Der Container <code>EcuMFixedGeneral</code> ist optional (<code>0..1</code>).</li>\n<li>Die Schalter <code>EcuMTTIIEnabled</code>, <code>EcuMIncludeNvramMgr</code>, <code>EcuMIncludeNvM</code> und <code>EcuMIncludeComM</code> sind als Boolesche Parameter typisiert und bedingen die Generierung der Schnittstellen zu den jeweiligen BSW-Modulen.</li>\n<li>Wird TTII konfiguriert, muss die Referenz <code>EcuMTTIIWakeupSourceRef</code> auf eine gültige Weckquelle aus der Menge der <code>EcuMWakeupSource</code>-Container verweisen (Kardinalität <code>1..*</code>).</li>\n</ul>"}, {"id": "FIG-bd49870c4349e2f0", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des ECU-Konfigurationsparametersatzes (ECUC) für das AUTOSAR-BswM-/EcuM-Modul <code>EcuMFixed</code> (ECU State Manager Fixed). Dargestellt ist die Metamodell-Struktur des Konfigurationscontainers <code>EcuMFixedGeneral</code> mit seinen enthaltenen Parametern und Referenzen sowie die Beziehung zum allgemeinen EcuM-Container <code>EcuMWakeupSource</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li>Container <code>EcuMFixedGeneral: EcucParamConfContainerDef</code> mit Multiplizität <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>.</li>\n<li>Aggregierte Konfigurationsparameter (<code>+parameter</code> via Komposition):</li>\n<li><code>EcuMTTIIEnabled: EcucBooleanParamDef</code> (Aktivierung von Time-Triggered Interfaces).</li>\n<li><code>EcuMIncludeNvramMgr: EcucBooleanParamDef</code> (Einbindung des NVRAM-Managers).</li>\n<li><code>EcuMIncludeNvM: EcucBooleanParamDef</code> (Einbindung des NVM-Treibers/Moduls).</li>\n<li><code>EcuMIncludeComM: EcucBooleanParamDef</code> (Einbindung des Communication Managers).</li>\n<li>Aggregierte Referenz (<code>+reference</code> via Komposition):</li>\n<li><code>EcuMTTIIWakeupSourceRef: EcucSymbolicNameReferenceDef</code> verweist mit <code>+destination</code> auf den externen Container <code>EcuMWakeupSource: EcucParamConfContainerDef</code> (from <code>EcuM</code>) mit Multiplizität <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = *</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne Ausführungssemantik oder Laufzeitsequenzen. Die Parameter steuern die Codegenerierung bzw. Vorkompilierungsvarianten (z. B. Einbindung von NvM, NvramMgr, ComM und TTII-Unterstützung). Die symbolische Referenz <code>EcuMTTIIWakeupSourceRef</code> verknüpft die Time-Triggered-Interface-Funktionalität mit einer oder mehreren im System definierten Weckquellen (<code>EcuMWakeupSource</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Konfigurationsspezifikation für AUTOSAR Classic BSW-Generatoren. Implementierer und Konfiguratoren müssen beachten:</p>\n<ul class=\"fig-list\">\n<li>Der Container <code>EcuMFixedGeneral</code> ist optional (<code>0..1</code>).</li>\n<li>Die Schalter <code>EcuMTTIIEnabled</code>, <code>EcuMIncludeNvramMgr</code>, <code>EcuMIncludeNvM</code> und <code>EcuMIncludeComM</code> sind als Boolesche Parameter typisiert und bedingen die Generierung der Schnittstellen zu den jeweiligen BSW-Modulen.</li>\n<li>Wird TTII konfiguriert, muss die Referenz <code>EcuMTTIIWakeupSourceRef</code> auf eine gültige Weckquelle aus der Menge der <code>EcuMWakeupSource</code>-Container verweisen (Kardinalität <code>1..*</code>).</li>\n</ul>"}, {"id": "FIG-a096802ce3d4125a", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des ECU-Konfigurationsparametersatzes (ECUC) für das AUTOSAR-BswM-/EcuM-Modul <code>EcuMFixed</code> (ECU State Manager Fixed). Dargestellt ist die Metamodell-Struktur des Konfigurationscontainers <code>EcuMFixedGeneral</code> mit seinen enthaltenen Parametern und Referenzen sowie die Beziehung zum allgemeinen EcuM-Container <code>EcuMWakeupSource</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li>Container <code>EcuMFixedGeneral: EcucParamConfContainerDef</code> mit Multiplizität <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>.</li>\n<li>Aggregierte Konfigurationsparameter (<code>+parameter</code> via Komposition):</li>\n<li><code>EcuMTTIIEnabled: EcucBooleanParamDef</code>.</li>\n<li><code>EcuMIncludeComM: EcucBooleanParamDef</code>.</li>\n<li>Aggregierte Referenz (<code>+reference</code> via Komposition):</li>\n<li><code>EcuMTTIIWakeupSourceRef: EcucSymbolicNameReferenceDef</code> verweist mit <code>+destination</code> auf den Container <code>EcuMWakeupSource: EcucParamConfContainerDef</code> (from <code>EcuM</code>) mit Multiplizität <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = *</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne Ausführungssemantik oder Laufzeitsequenzen. Die Parameter steuern Vorkompilierungsvarianten für TTII und ComM. Die symbolische Referenz <code>EcuMTTIIWakeupSourceRef</code> bindet eine konfigurierte Weckquelle (<code>EcuMWakeupSource</code>) an die TTII-Logik.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Konfigurationsspezifikation für AUTOSAR Classic BSW-Generatoren. Implementierer und Konfiguratoren müssen beachten:</p>\n<ul class=\"fig-list\">\n<li>Der Container <code>EcuMFixedGeneral</code> ist optional (<code>0..1</code>).</li>\n<li>Die verbliebenen Schalter <code>EcuMTTIIEnabled</code> und <code>EcuMIncludeComM</code> steuern spezifische Schnittstellen der EcuM-Fixed-Variante.</li>\n<li>Bei Nutzung von TTII muss <code>EcuMTTIIWakeupSourceRef</code> auf mindestens eine definierte Weckquelle (<code>EcuMWakeupSource</code>, Multiplizität <code>1..*</code>) verweisen.</li>\n</ul>"}, {"id": "FIG-6e53b1e83a346f55", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des ECU-Konfigurationsparametersatzes (ECUC) für das AUTOSAR-BswM-/EcuM-Modul <code>EcuMFixed</code> (ECU State Manager Fixed). Dargestellt ist die Metamodell-Struktur des Konfigurationscontainers <code>EcuMFixedGeneral</code> mit seinen enthaltenen Parametern und Referenzen sowie die Beziehung zum allgemeinen EcuM-Container <code>EcuMWakeupSource</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li>Container <code>EcuMFixedGeneral: EcucParamConfContainerDef</code> mit Multiplizität <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>.</li>\n<li>Aggregierte Konfigurationsparameter (<code>+parameter</code> via Komposition):</li>\n<li><code>EcuMTTIIEnabled: EcucBooleanParamDef</code> mit Multiplizität <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>.</li>\n<li><code>EcuMIncludeComM: EcucBooleanParamDef</code> mit Multiplizität <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>.</li>\n<li>Aggregierte Referenz (<code>+reference</code> via Komposition):</li>\n<li><code>EcuMTTIIWakeupSourceRef: EcucSymbolicNameReferenceDef</code> mit Multiplizität <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>. Verweist mit <code>+destination</code> auf den externen Container <code>EcuMWakeupSource: EcucParamConfContainerDef</code> (from <code>EcuM</code>) mit Multiplizität <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 32</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne Ausführungssemantik oder Laufzeitsequenzen. Die Parameter steuern Vorkompilierungsvarianten für TTII und ComM. Die symbolische Referenz <code>EcuMTTIIWakeupSourceRef</code> bindet eine konfigurierte Weckquelle (<code>EcuMWakeupSource</code>) an die TTII-Logik.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Konfigurationsspezifikation für AUTOSAR Classic BSW-Generatoren. Implementierer und Konfiguratoren müssen beachten:</p>\n<ul class=\"fig-list\">\n<li>Sämtliche Kindelemente des Containers <code>EcuMFixedGeneral</code> (<code>EcuMTTIIEnabled</code>, <code>EcuMTTIIWakeupSourceRef</code>, <code>EcuMIncludeComM</code>) besitzen die explizite Multiplizität <code>0..1</code>.</li>\n<li>Die Anzahl der im System konfigurierbaren Weckquellen (<code>EcuMWakeupSource</code>) ist auf maximal 32 beschränkt (Kardinalität <code>1..32</code>), entsprechend der gängigen 32-Bit-Masken-Repräsentation von Weckquellen in AUTOSAR.</li>\n<li>Die Referenz <code>EcuMTTIIWakeupSourceRef</code> ist optional (<code>0..1</code>) und darf nur auf eine gültige Weckquelle aus diesem Wertebereich zeigen.</li>\n</ul>"}], "trans": [{"from": "FIG-4050d20ac47aa707", "to": "FIG-bd49870c4349e2f0", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-bd49870c4349e2f0", "to": "FIG-a096802ce3d4125a", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Parameter <code>EcuMIncludeNvramMgr: EcucBooleanParamDef</code> entfällt im Container <code>EcuMFixedGeneral</code>.</li>\n<li>Parameter <code>EcuMIncludeNvM: EcucBooleanParamDef</code> entfällt im Container <code>EcuMFixedGeneral</code>.</li>\n</ul>"}, {"from": "FIG-a096802ce3d4125a", "to": "FIG-6e53b1e83a346f55", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Multiplizität des referenzierten Containers <code>EcuMWakeupSource</code> (<code>EcucParamConfContainerDef</code>) von <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = *</code> auf <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 32</code> eingeschränkt.</li>\n<li>Multiplizitätsangaben <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code> explizit für Parameter <code>EcuMTTIIEnabled</code>, Referenz <code>EcuMTTIIWakeupSourceRef</code> und Parameter <code>EcuMIncludeComM</code> ergänzt.</li>\n</ul>"}]};
